export const formatInitials = (name: string): string => {
  if (name === null) {
    return '';
  }

  const words = name.split(' ');
  const numbemrOfWords = words.length;
  const firstWordInitialLetter = name.charAt(0);
  const lastWordInitialLetter = numbemrOfWords > 1 ? words[numbemrOfWords - 1].charAt(0) : '';

  return String(firstWordInitialLetter + lastWordInitialLetter).toUpperCase();
};
